// Validate & normalize W4 intake payload + attach CONFIG
// Input sources: Webhook (payload) + Config (W4)

function latestFrom(nodeName){
  try{
    const items = $items(nodeName, 0, $runIndex);
    if (items && items.length) return items[0].json;
  }catch{}
  return null;
}

const cfg  = latestFrom('Config (W4)')?.CONFIG || ($json.CONFIG || {});
const body = latestFrom('Webhook (W4 Intake)') || $json || {};

// Expected fields from W3 → W4
const orderId       = body.orderId || body.amazonOrderId || body.AmazonOrderId;
let pageImageUrls   = Array.isArray(body.pageImageUrls) ? body.pageImageUrls : [];
const coverPdfR2Key = body.coverPdfR2Key || null;
const coverPdfUrl   = body.coverPdfUrl   || null;

// Optional context
const shippingAddress = body.shippingAddress || body.shipping_address || {};
const customer        = body.customer || { email: body.customer_email, name: body.customer_name };
const title           = body.title || 'Little Hero Book';

if (!orderId) throw new Error('W4 validation: Missing orderId from W3 → W4');
if (!Array.isArray(pageImageUrls)) throw new Error('W4 validation: pageImageUrls must be an array');
if (pageImageUrls.length !== 15) {
  throw new Error(`W4 validation: expected exactly 15 pageImageUrls (p00..p14); received ${pageImageUrls.length}`);
}
if (!(coverPdfR2Key || coverPdfUrl)) {
  throw new Error('W4 validation: provide either coverPdfR2Key (preferred) or coverPdfUrl');
}

// Light normalization: trim and ensure non-empty strings
pageImageUrls = pageImageUrls.map((u, i) => {
  const s = String(u || '').trim();
  if (!s) throw new Error(`W4 validation: pageImageUrls[${i}] is empty`);
  return s;
});

// Interior PDF filename/key
const pdfFilename = `interior_${orderId}.pdf`;
const pdfR2Key    = `book-mvp-simple-adventure/orders/${orderId}/${pdfFilename}`;

return [{
  json: {
    CONFIG: cfg,
    orderId,
    pageImageUrls,
    coverPdfR2Key,
    coverPdfUrl,
    shippingAddress,
    customer,
    title,
    pdfFilename,
    pdfR2Key
  }
}];

const j = $input.first().json || {};
console.log('W4 Intake Ack →', {
  orderId: j.orderId,
  pages: j.pageImageUrls?.length || 0,
  coverSource: j.coverPdfR2Key ? 'R2 key' : (j.coverPdfUrl ? 'URL' : 'missing')
});
return [{ json: j }];

// Build pages_html for PDFMonkey at 8.75×8.75 in (bleed) from pageImageUrls
const j = $input.first().json || {};
const pages = Array.isArray(j.pageImageUrls) ? j.pageImageUrls : [];
if (pages.length === 0) throw new Error('No pageImageUrls to build pages_html');

const css = `
