    @page { size: 8.75in 8.75in; margin: 0; }
    html, body { margin:0; padding:0; }
    .page { width:8.75in; height:8.75in; page-break-after: always; }
    .bg { width:100%; height:100%; object-fit: cover; display:block; }
  </style>
`;

const pagesHtml = pages.map(url => {
  return `<section class="page"><img class="bg" src="${url}" alt="" /></section>`;
}).join('\n');

return [{
  json: {
    ...j,
    pages_html: `${css}\n${pagesHtml}`
  }
}];

const d = $input.first().json;
const tpl = d.CONFIG?.pdfMonkey?.templateId;
if (!tpl || tpl === 'REPLACE_WITH_PDFMONKEY_TEMPLATE_ID') {
  throw new Error('Missing PDFMonkey templateId in Config (W4). Please set CONFIG.pdfMonkey.templateId');
}
return [{
  json: {
    ...d,
    document: {
      document_template_id: tpl,
      status: 'pending',
      meta: { _filename: d.pdfFilename },
      payload: { pages_html: d.pages_html }
    }
  }
}];

const createResp = $input.first().json;
const doc = createResp.data || createResp.document || createResp;
const docId = doc.id || doc.data?.id;
if (!docId) throw new Error('PDFMonkey create response missing id');

const http = this.helpers.httpRequest;
const token = $json.CONFIG?.pdfMonkey?.token; if (!token) { throw new Error('Missing PDFMonkey token in CONFIG'); }
const AUTH_HEADER = { Authorization: `Bearer ${token}` };

let status = doc.status || 'queued';
let downloadUrl = doc.download_url || null;
let attempts = 0;
async function sleep(ms){ return new Promise(r=>setTimeout(r, ms)); }

while (attempts < 20) {
  if (status === 'success' && downloadUrl) break;
  const resp = await http({ method:'GET', url:`https://api.pdfmonkey.io/api/v1/documents/${docId}`, json:true, headers: AUTH_HEADER });
  const d = resp.data || resp.document || resp;
  status = d.status;
  downloadUrl = d.download_url || d.file_url || null;
  if (status === 'success' && downloadUrl) break;
  attempts++; const delay = Math.min(6000, 2000 * (1 + attempts/3)); await sleep(delay);
}
if (status !== 'success' || !downloadUrl) throw new Error(`PDF not ready (status=${status})`);

const orderId = $json.orderId;
const pdfFilename = $json.pdfFilename || `interior_${orderId}.pdf`;
const pdfR2Key = `book-mvp-simple-adventure/orders/${orderId}/${pdfFilename}`;
return [{ json: { ...$json, pdfMonkeyDocumentId: docId, pdfDownloadUrl: downloadUrl, pdfR2Key } }];

