}

function isUrl(s){ return typeof s === 'string' && /^https?:\/\//i.test(s); }

const now = new Date();
const amzDate = now.toISOString().replace(/[-:]/g, '').replace(/\..+/, '') + 'Z';
const date = amzDate.slice(0, 8);
const service = 's3';
const rgn = region || 'auto';

function hmac(key, data){ return require('crypto').createHmac('sha256', key).update(data).digest(); }
function sha256Hex(data){ return require('crypto').createHash('sha256').update(data).digest('hex'); }
function toHex(buffer){ return buffer.toString('hex'); }

function presignKey(key, expires=3600){
  const host = endpointHost;
  const objectKey = encodeURIComponent(key).replace(/%2F/g,'/');
  const method = 'GET';
  const canonicalUri = `/${bucket}/${objectKey}`;
  const credentialScope = `${date}/${rgn}/${service}/aws4_request`;
  const credential = `${accessKeyId}/${credentialScope}`;
  const signedHeaders = 'host';
  const q = new URLSearchParams({
    'X-Amz-Algorithm': 'AWS4-HMAC-SHA256',
    'X-Amz-Credential': credential,
    'X-Amz-Date': amzDate,
    'X-Amz-Expires': String(expires),
    'X-Amz-SignedHeaders': signedHeaders,
  });
  const canonicalQueryString = q.toString();
  const canonicalHeaders = `host:${host}\n`;
  const payloadHash = 'UNSIGNED-PAYLOAD';
  const canonicalRequest = [method, canonicalUri, canonicalQueryString, canonicalHeaders, signedHeaders, payloadHash].join('\n');
  const stringToSign = ['AWS4-HMAC-SHA256', amzDate, credentialScope, sha256Hex(canonicalRequest)].join('\n');
  const kDate = hmac(Buffer.from('AWS4'+secretAccessKey, 'utf8'), date);
  const kRegion = hmac(kDate, rgn);
  const kService = hmac(kRegion, service);
  const kSigning = hmac(kService, 'aws4_request');
  const signature = toHex(hmac(kSigning, stringToSign));
  const url = `https://${host}/${bucket}/${objectKey}?${canonicalQueryString}&X-Amz-Signature=${signature}`;
  return url;
}

