const coverRef    = j.coverPdfR2Key || j.coverPdfUrl;
if (!interiorRef || !coverRef) throw new Error('Missing R2 refs for interior or cover');

const interiorSignedUrl = isUrl(interiorRef) ? interiorRef : presignKey(interiorRef, 3600);
const coverSignedUrl    = isUrl(coverRef)    ? coverRef    : presignKey(coverRef, 3600);

return [{ json: { ...j, interiorSignedUrl, coverSignedUrl } }];

